package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.special.Beta;
import org.apache.commons.math3.exception.MathException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FDistributionImpl.inverseCumulativeProbability
 */
public class FDistributionImpl_inverseCumulativeProbability_TriageGen2Test {

    private FDistributionImpl fDistribution;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        // Standard F-distribution with d1=5, d2=5
        fDistribution = new FDistributionImpl(5.0, 5.0);
    }

    @Test
    public void testInverseCumulativeProbability_WhenPIsZero() throws MathException {
        double p = 0.0;
        double expected = 0.0;
        double actual = fDistribution.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is 0, return should be 0.0", expected, actual, DELTA);
    }

    @Test
    public void testInverseCumulativeProbability_WhenPIsOne() throws MathException {
        double p = 1.0;
        double expected = Double.POSITIVE_INFINITY;
        double actual = fDistribution.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is 1, return should be Positive Infinity", expected, actual, DELTA);
    }

    @Test
    public void testInverseCumulativeProbability_WhenPIsBetweenZeroAndOne() throws MathException {
        // Test a standard value. For F(5,5), the median (p=0.5) is 1.0
        double p = 0.5;
        double expected = 1.0;
        double actual = fDistribution.inverseCumulativeProbability(p);

        // Note: We use a slightly larger delta for super implementation accuracy if needed, 
        // but 1e-10 is standard for math tests.
        Assert.assertEquals("When p is 0.5, return should match super implementation (median)", expected, actual, 1e-6);
    }

    @Test
    public void testInverseCumulativeProbability_BoundaryValues() throws MathException {
        // Testing values very close to boundaries to ensure branch coverage for the super call
        double pSmall = 0.0000001;
        double pLarge = 0.9999999;

        double actualSmall = fDistribution.inverseCumulativeProbability(pSmall);
        double actualLarge = fDistribution.inverseCumulativeProbability(pLarge);

        Assert.assertTrue("Small p should yield a finite positive value", actualSmall > 0);
        Assert.assertTrue("Large p should yield a finite positive value", actualLarge > actualSmall);
    }

    @Test(expected = MathException.class)
    public void testInverseCumulativeProbability_WhenPIsInvalid() throws MathException {
        // Although not explicitly handled by the provided code snippet's if-statements,
        // the super call is expected to throw MathException for p < 0 or p > 1.
        double p = -0.1;
        fDistribution.inverseCumulativeProbability(p);
    }
}
